-- 067: Phase 5 Part 1 — the criterion catalogue (LLD_PHASE5_AUTHORING §a–§d).
--
-- WHY: Phase 4's standard views count against an ENGINE-CENSUS denominator
-- (denominator_complete=false) and carry a RULE-derived WCAG level per
-- criterion (migration 063 propagated the axe rule's level tag). Both are
-- honest lower bounds and both are wrong for a report that must say
-- "N of M criteria". The fix is a ratified criterion catalogue per
-- standard, ingested from hash-pinned normative documents a human
-- obtained (the axe-core discipline, D-461) — Plimsol generates nothing.
--
-- THREE CHANGES, all idempotent:
--   1. standard sets gain a REVISION: a ratified set is frozen from REVIEW
--      onward, so attaching a catalogue to an ACTIVE set would mutate a
--      ratified object. A new revision of the same (standard, version) is
--      authored, ratified and activated instead; the old revision retires.
--   2. s5_criteria: the catalogue rows, owned by a standard set, so the
--      set is "catalogue + maps under one content hash, one ratification".
--   3. the five artifact pins (sha256 + source URL + retrieval date).
--
-- The ratification REPLAY (revision-2 sets, criteria, copied maps with
-- catalogue levels) is appended below the DDL after the GO — see
-- VERIFICATION_PHASE5_PART1.md for the transcript it reproduces.
BEGIN;

-- 1. revisions -----------------------------------------------------------
ALTER TABLE s5_standard_map_sets
    ADD COLUMN IF NOT EXISTS revision INT NOT NULL DEFAULT 1;
ALTER TABLE s5_standard_map_sets
    DROP CONSTRAINT IF EXISTS s5_standard_map_sets_unique_version;
DO $$
BEGIN
    IF NOT EXISTS (SELECT 1 FROM pg_constraint
                   WHERE conname = 's5_standard_map_sets_unique_revision') THEN
        ALTER TABLE s5_standard_map_sets
            ADD CONSTRAINT s5_standard_map_sets_unique_revision
            UNIQUE (standard, standard_version, revision);
    END IF;
END $$;

-- 2. the catalogue rows ----------------------------------------------------
CREATE TABLE IF NOT EXISTS s5_criteria (
    id               BIGSERIAL PRIMARY KEY,
    set_id           BIGINT NOT NULL REFERENCES s5_standard_map_sets (id),
    standard         VARCHAR(24) NOT NULL,
    standard_version VARCHAR(64) NOT NULL,
    criterion        VARCHAR(32) NOT NULL,   -- the standard's OWN numbering
    title            VARCHAR(160) NOT NULL,
    level            VARCHAR(3) NOT NULL,    -- per CRITERION, from the document
    ordinal          INT NOT NULL,           -- document order
    binds_wcag_sc    VARCHAR(16),            -- EN 9.1.1.1 -> 1.1.1; 508 -> itself
    source_ref       JSONB NOT NULL DEFAULT '{}'::jsonb,
    created_at       TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    CONSTRAINT s5_criteria_level_known CHECK (level IN ('A','AA','AAA')),
    CONSTRAINT s5_criteria_standard_known CHECK (
        standard IN ('WCAG22','EN301549','SECTION508')),
    CONSTRAINT s5_criteria_unique_in_set UNIQUE (set_id, criterion)
);
CREATE INDEX IF NOT EXISTS s5_criteria_set_idx ON s5_criteria (set_id);

